// Normalize incoming event into standard format
const payload = $json;
const event = {
  type: payload.type || 'message',
  channel: payload.channel || 'whatsapp',
  userId: payload.userId || payload.user_id || $parameter.userId || 'demo',
  from: payload.from || payload.sender || payload.email || null,
  text: payload.text || payload.body || payload.subject || '',
  meta: payload.meta || {},
  raw: payload
};
return [{ json: { event } }];

// Parse Planner output and extract action
let action = {};
try {
  const txt = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content || $json.text || '{}';
  action = JSON.parse(txt);
} catch(e) {
  // Fallback: naive keyword detection
  const text = ($json.event || {}).text || '';
  if (text.toLowerCase().includes('book') || text.toLowerCase().includes('schedule') || text.toLowerCase().includes('meeting')) {
    action = { intent: 'schedule_meeting', entities: {}, confidence: 0.7, reasoning: 'Keyword match' };
  } else if (text.toLowerCase().includes('quote') || text.toLowerCase().includes('price') || text.toLowerCase().includes('cost')) {
    action = { intent: 'generate_quote', entities: {}, confidence: 0.7, reasoning: 'Keyword match' };
  } else if (text.length > 0) {
    action = { intent: 'send_message', entities: {}, confidence: 0.6, reasoning: 'Default response' };
  } else {
    action = { intent: 'send_message', entities: {}, confidence: 0.5, reasoning: 'Empty fallback' };
  }
}
return [{ json: { action, originalEvent: $json.event, originalContext: $node['Memory - Recall Context'].rows || [] } }];

// Extract drafted message
let message = '';
try {
  message = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content || $json.text || '';
} catch(e) {
  message = 'Thank you for your message!';
}

const evt = $node['Parse Planner Output'].json.originalEvent;
return [{ json: {
  to: evt.from,
  channel: evt.channel || 'whatsapp',
  message: message,
  originalEvent: evt
} }];

// Build calendar event from planner entities and event data
const evt = $node['Parse Planner Output'].json.originalEvent;
const entities = $node['Parse Planner Output'].json.action.entities || {};

const startTime = entities.startTime || entities.meetingTime || new Date(Date.now() + 24*3600*1000).toISOString();
const duration = entities.duration || 30;
const endTime = entities.endTime || new Date(new Date(startTime).getTime() + duration*60000).toISOString();

return [{ json: {
  calendarPayload: {
    summary: entities.summary || `Meeting with ${evt.from}`,
    start: { dateTime: startTime, timeZone: 'Asia/Kolkata' },
    end: { dateTime: endTime, timeZone: 'Asia/Kolkata' },
    attendees: [{ email: evt.from }],
    description: `Auto-created from: ${evt.text}`
  },
  originalEvent: evt
} }];

// Generate quote from planner entities
const evt = $node['Parse Planner Output'].json.originalEvent;
const entities = $node['Parse Planner Output'].json.action.entities || {};

const quote = {
  id: 'Q-' + Date.now(),
  to: evt.from,
  items: entities.items || [{ description: 'Service', price: entities.price || 10000 }],
  total: entities.total || entities.price || 10000,
  validUntil: new Date(Date.now() + 7*24*3600*1000).toISOString().split('T')[0]
};

const message = `Here is your quote (ID: ${quote.id}).\nTotal: ₹${quote.total}\nValid until: ${quote.validUntil}\nReply to confirm.`;

return [{ json: { quote, message, originalEvent: evt } }];

// Parse suggestions and store
let suggestions = [];
try {
  const txt = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content || '[]';
  suggestions = JSON.parse(txt);
} catch(e) {
  suggestions = [{ id: 's1', title: 'Auto follow-ups', confidence: 0.8, description: 'Set up automatic follow-up chain', suggestedAction: {} }];
}

// Store each suggestion
const promises = suggestions.map(s => {
  return $node['Observer - Store Suggestion'].run({ json: { suggestion: s } });
});

return [{ json: { suggestions: suggestions.length, timestamp: new Date().toISOString() } }];
